        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .bind(lens: try FfiConverterTypeCameraLens.read(from: &buf)
        )
        
        case 2: return .unbind
        
        case 3: return .restart(lens: try FfiConverterTypeCameraLens.read(from: &buf)
        )
        
        case 4: return .takePhoto
        
        case 5: return .beginRecording
        
        case 6: return .endRecording(discard: try FfiConverterBool.read(from: &buf)
        )
        
        case 7: return .readClip
        
        case 8: return .deliver
        
        case 9: return .discard
        
        case 10: return .setTorch(on: try FfiConverterBool.read(from: &buf)
        )
        
        case 11: return .setZoom(ratio: try FfiConverterFloat.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CaptureAction, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .bind(lens):
            writeInt(&buf, Int32(1))
            FfiConverterTypeCameraLens.write(lens, into: &buf)
            
        
        case .unbind:
            writeInt(&buf, Int32(2))
        
        
        case let .restart(lens):
            writeInt(&buf, Int32(3))
