            writeInt(&buf, Int32(7))
        
        
        case let .attach(viewToken):
            writeInt(&buf, Int32(8))
            FfiConverterUInt64.write(viewToken, into: &buf)
            
        
        case .detach:
            writeInt(&buf, Int32(9))
        
        
        case let .seek(positionMs):
            writeInt(&buf, Int32(10))
            FfiConverterUInt64.write(positionMs, into: &buf)
            
        
        case let .rate(rate):
            writeInt(&buf, Int32(11))
            FfiConverterFloat.write(rate, into: &buf)
            
        
        case let .looping(looping):
            writeInt(&buf, Int32(12))
            FfiConverterBool.write(looping, into: &buf)
            
        
        case let .readahead(ms):
            writeInt(&buf, Int32(13))
